pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit principle)
    // We apply a non-linear penalty to small residuals that are likely to become "dead space"
    // based on the average size of upcoming items (represented by mean_residual approximation).
    let mut score = post * (1.0 + (mean_residual / (post + 1.0)).powf(0.5));

    // If this is a new bin, penalize it heavily early in the stream, 
    // but allow it to be chosen if the fit is extremely poor across all existing bins.
    if bin_residual == bin_capacity {
        score = 50.0 + (progress * 100.0);
    } else {
        // Favor bins that leave just enough room for the next item (Lookahead optimization)
        if next_item_size > 0 {
            if post >= next_item_size as f64 {
                score -= (next_item_size as f64) * 0.8;
            } else {
                // Penalize if the current fit prevents the next item from fitting
                score += (next_item_size as f64 - post) * 1.5;
            }
        }

        // Penalty for creating a bin that is almost empty but not quite, 
        // especially when many bins are already open.
        score += (open_bins_count as f64) * (post / bin_capacity as f64) * 10.0;

        // If this is the last bin that can fit the item, prioritize it to avoid 
        // unnecessary new bin creation (fitting_bins_count constraint).
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
}

