    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining capacity (Best Fit principle)
    // We aim to minimize this, but add penalties for "bad" remaining space.
    let mut score = post;

    // Penalty for creating a "sliver" (fragmentation)
    // Slivers (1-9) are usually harder to fill than mid-sized residuals
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead coupling: If the next item is large, favor larger residuals
    if next_item_size > 0 {
        let next_req = next_item_size as f64;
        if post < next_req {
            // Severe penalty if this bin won't fit the next item when it could have
            score += 50.0 * (1.0 - progress);
        }
    }

    // Dynamic Pressure: As the stream progresses, prioritize tighter packing
    // to avoid leaving too many bins partially full at the end.
    let tightness_factor = (1.0 - progress) * (mean_residual / bin_capacity as f64);
    score += tightness_factor * 15.0;

    // Threshold logic for new bins: 
    // If bin is empty (residual == capacity), we only open if the average
    // residual of existing bins is already very high (indicating poor packing).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the average residual is significantly 
            // worse than a fresh start would be.
            score = mean_residual * 0.8;
        }
    } else if fitting_bins_count == 1 {
        // High priority to finish a bin if it's the last one that can fit the item
        score -= 10.0;
    }

    score
