pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space) 
    // but weigh it against the item size to avoid creating "orphaned" small space.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Coupling: If next_item_size is large, favor keeping larger residuals (lower penalty for higher post_residual).
    if next_item_size > 0 {
        let diff = (post_residual as f64) - (next_item_size as f64);
        if diff < 0.0 {
            // If the next item won't fit, penalize this placement heavily
            score += 50.0;
        } else {
            // If it fits, reward the bin that leaves exactly enough space for the next item
            score -= (100.0 - diff.abs()) * 0.5;
        }
    }

    // 3. Global State: If we are near the end of the stream, prioritize tight packing (Best Fit).
    // If we are early, allow for more flexibility.
    if progress > 0.8 {
        score += (post_residual as f64) * 2.0;
    }

    // 4. New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity), score it based on whether we should force a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very low (bins are full)
        // or if we have very few open bins.
        score = 150.0 - (mean_residual * 0.8) - (open_bins_count as f64 * 0.5);
    } else {
        // If it's an existing bin, reduce score if it's the last chance (fitting_bins_count == 1)
        // to prevent opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the residual space; we want to minimize this (Best Fit principle).
    let mut score = post_residual as f64;

