    if !is_new_bin {
        // If the post-residual is smaller than the next item, it's "dead space".
        // Heavily penalize if the next item cannot fit, unless we are near the end.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }

        // Reward placements that leave a residual which is a multiple of 10 or 25,
        // as these are "clean" slots for subsequent items.
        if post_residual % 10 == 0 {
            score -= 5.0;
        }
    } else {
        // If considering a new bin, penalize it based on how many fitting bins currently exist.
        // Opening a new bin is expensive.
        score += (fitting_bins_count as f64) * 20.0;

        // As we approach the end of the stream, opening new bins becomes increasingly costly.
        score += (progress * 50.0);
    }

